args.script:
(() => {
  const txt = document.body.innerText;
  return {url: location.href, title: document.title, text: txt.slice(0, 5000)};
})()

(() => {
  const buttons = [...document.querySelectorAll('button, [role=button], a')].map((el, i) => ({
    i,
    tag: el.tagName,
    text: (el.innerText || el.textContent || '').trim().replace(/\s+/g,' ').slice(0,100),
    aria: el.getAttribute('aria-label'),
    data: el.getAttribute('data-testid'),
    type: el.getAttribute('type'),
    id: el.id,
    href: el.href || null
  })).filter(x => x.text || x.aria || x.data || x.href);
  return {url: location.href, title: document.title, buttons: buttons.slice(0,220), body: document.body.innerText.slice(0,3000)};
})()

(() => {
  const els = [...document.querySelectorAll('button, span, div, td')];
  return els.map((el, i) => ({
    i,
    tag: el.tagName,
    role: el.getAttribute('role'),
    text: (el.innerText || el.textContent || '').trim().replace(/\s+/g,' ').slice(0,80),
    aria: el.getAttribute('aria-label'),
    data: el.getAttribute('data-testid'),
    disabled: el.disabled || el.getAttribute('aria-disabled'),
    classes: el.className && String(el.className).slice(0,80)
  })).filter(x => x.text || x.aria || x.data).slice(0,300);
})()

(() => {
  const out = [];
  for (const el of document.querySelectorAll('button, [role="button"], td, [data-date], [aria-label]')) {
    const text = (el.innerText || el.textContent || '').trim().replace(/\s+/g,' ');
    const aria = el.getAttribute('aria-label');
    const dataDate = el.getAttribute('data-date') || el.getAttribute('data-testid');
    if ((text || aria || dataDate) && (dataDate || /2026|May|June|Jun|17|18|19|Next|Previous|Search|Check/i.test(text + ' ' + aria))) {
      out.push({tag: el.tagName, text: text.slice(0,120), aria, dataDate, role: el.getAttribute('role'), disabled: el.disabled || el.getAttribute('aria-disabled')});
    }
  }
  return {url: location.href, title: document.title, items: out.slice(0,200), body: document.body.innerText.slice(0,2000)};
})()
